8	// ============================================================================
9	// module.cpp
10	//
11	// Module = a loaded .vxbin (device-side image + parsed symbol table).
12	// Kernel = a named entry point inside a module, with its PC cached.
13	//
14	// .vxbin layout:
15	//   [min_vma   : 8 bytes LE]
16	//   [max_vma   : 8 bytes LE]
17	//   [binary bytes ...]                                     <- length = bin_sz
18	//   --- optional symbol-table footer ---
19	//   [string blob (variable, all symbol names back-to-back, NUL-separated)]
20	//   [entries: N × { name_off:4, name_len:2, _pad:2, pc:8 }  = 16 bytes each ]
21	//   [n_symbols : 4 bytes LE]
22	//   [magic     : 8 bytes 'VXSYMTAB']                       <- end of file
23	//
24	// Loader checks the last 8 bytes for the magic. If present, parses
25	// backward to recover the symbol table. If absent, falls back to a single
26	// "main" entry whose PC is min_vma.
27	// ============================================================================
28	
29	#include "vortex2_internal.h"
30	
31	#include <cstdint>
32	#include <cstring>
33	#include <fstream>
34	#include <vector>
35	
36	namespace vx {
37	
38	// ----------------------------------------------------------------------------
39	// Module
40	// ----------------------------------------------------------------------------
41	
42	Module::Module(Device* dev, Buffer* image, uint64_t base_addr)
43	    : device_(dev), image_(image), base_addr_(base_addr) {
44	    device_->retain();
45	    // image_ ref was already created by Buffer::reserve.
46	}
47	
48	Module::~Module() {
49	    // Cached kernels hold a ref on this module; once we're being deleted,
50	    // they're already gone (release order ensures kernels drop us first).
51	    if (image_) image_->release();
52	    if (device_) device_->release();
53	}
54	
55	vx_result_t Module::load_file(Device* dev, const char* path, Module** out) {
56	    if (!dev || !path || !out) return VX_ERR_INVALID_VALUE;
57	    std::ifstream ifs(path, std::ios::binary);
58	    if (!ifs) return VX_ERR_INVALID_VALUE;
59	    ifs.seekg(0, ifs.end);
60	    auto file_sz = (size_t)ifs.tellg();
61	    ifs.seekg(0, ifs.beg);
62	    if (file_sz < 16) return VX_ERR_INVALID_VALUE;
63	
64	    std::vector<uint8_t> all(file_sz);
65	    ifs.read(reinterpret_cast<char*>(all.data()), file_sz);
66	    if (!ifs) return VX_ERR_INVALID_VALUE;
67	    return load_bytes(dev, all.data(), all.size(), out);
68	}
69	
70	vx_result_t Module::load_bytes(Device* dev, const void* bytes_, size_t size,
71	                               Module** out) {
72	    if (!dev || !bytes_ || size < 16 || !out) return VX_ERR_INVALID_VALUE;
73	    auto* bytes = static_cast<const uint8_t*>(bytes_);
74	
75	    const uint64_t min_vma = *reinterpret_cast<const uint64_t*>(bytes + 0);
76	    const uint64_t max_vma = *reinterpret_cast<const uint64_t*>(bytes + 8);
77	    if (max_vma <= min_vma) return VX_ERR_INVALID_VALUE;
78	    const uint64_t rt_sz = max_vma - min_vma;
79	
80	    // Sniff for the symbol footer. It lives at the END of the file; the bin
81	    // proper is everything between the 16-byte header and (start-of-footer).
82	    static const char kFooterMagic[8] = {'V','X','S','Y','M','T','A','B'};
83	    size_t footer_total = 0;
84	    uint32_t n_syms = 0;
85	    bool has_footer = false;
86	    if (size >= 16 + 12 &&
87	        std::memcmp(bytes + size - 8, kFooterMagic, 8) == 0) {
88	        n_syms = *reinterpret_cast<const uint32_t*>(bytes + size - 12);
89	        const size_t entries_sz = size_t(n_syms) * 16;
90	        if (size >= 16 + 12 + entries_sz) {
91	            footer_total = 12 + entries_sz;
92	            // String blob sits between the bin and the entries; we figure
93	            // its size out from the entries' (name_off, name_len) pairs.
94	            const uint8_t* entries_start = bytes + size - 12 - entries_sz;
95	            size_t max_end_off = 0;
96	            for (uint32_t i = 0; i < n_syms; ++i) {
97	                const uint8_t* e = entries_start + size_t(i) * 16;
98	                const uint32_t name_off = *reinterpret_cast<const uint32_t*>(e + 0);
99	                const uint16_t name_len = *reinterpret_cast<const uint16_t*>(e + 4);
100	                const size_t end_off = size_t(name_off) + name_len;
101	                if (end_off > max_end_off) max_end_off = end_off;
102	            }
103	            footer_total += max_end_off;   // string blob included
104	            if (footer_total <= size - 16) {
105	                has_footer = true;
106	            } else {
107	                footer_total = 0;
108	                n_syms = 0;
109	            }
110	        }
111	    }
112	
113	    const uint64_t bin_sz = size - 16 - footer_total;
114	    if (bin_sz > rt_sz) return VX_ERR_INVALID_VALUE;
115	    const uint8_t* bin = bytes + 16;
116	
117	    // Reserve the image's VMA range on the device.
118	    Buffer* image = nullptr;
119	    auto r = Buffer::reserve(dev, min_vma, rt_sz, 0, &image);
120	    if (r != VX_SUCCESS) return r;
121	
122	    // .text/.rodata read-only, .bss read-write.
123	    r = image->access(0, bin_sz, VX_MEM_READ);
124	    if (r != VX_SUCCESS) { image->release(); return r; }
125	    if (rt_sz > bin_sz) {
126	        r = image->access(bin_sz, rt_sz - bin_sz, VX_MEM_READ_WRITE);
127	        if (r != VX_SUCCESS) { image->release(); return r; }
128	    }
129	
130	    // Synchronously upload the binary payload + zero the BSS region.
131	    // Routed via dev_write (the CP's DMA on a CP-only-DMA backend); still
132	    // synchronous, so Module stays a pure synchronous primitive — the
133	    // caller doesn't need a queue handy to load a module.
134	    r = dev->dev_write(min_vma, bin, bin_sz);
135	    if (r != VX_SUCCESS) { image->release(); return r; }
136	    if (rt_sz > bin_sz) {
137	        std::vector<uint8_t> zeros(rt_sz - bin_sz, 0);
138	        r = dev->dev_write(min_vma + bin_sz, zeros.data(), rt_sz - bin_sz);
139	        if (r != VX_SUCCESS) { image->release(); return r; }
140	    }
141	
142	    // Build the Module. Symbol table comes from the footer if present;
143	    // otherwise we fall back to a single "main" entry at min_vma.
144	    Module* m = new Module(dev, image, min_vma);
145	    if (has_footer) {
146	        const uint8_t* entries_start = bytes + size - 12 - size_t(n_syms) * 16;
147	        const uint8_t* strings_start = bytes + 16 + bin_sz;
148	        for (uint32_t i = 0; i < n_syms; ++i) {
149	            const uint8_t* e = entries_start + size_t(i) * 16;
150	            const uint32_t name_off = *reinterpret_cast<const uint32_t*>(e + 0);
151	            const uint16_t name_len = *reinterpret_cast<const uint16_t*>(e + 4);
152	            const uint64_t pc       = *reinterpret_cast<const uint64_t*>(e + 8);
153	            m->symbols_.push_back({
154	                std::string(reinterpret_cast<const char*>(strings_start + name_off),
155	                            name_len),
156	                pc
157	            });
158	        }
159	        // A single-kernel vxbin (the regression tests) carries exactly one
160	        // entry stub. Expose "main" @ min_vma too — the same launch entry
161	        // used for stub-less single-entry images — so callers using the
162	        // conventional entry name resolve it whether or not the compiler
163	        // emitted a per-kernel entry stub. Multi-kernel images keep their
164	        // explicit names.
165	        if (m->symbols_.size() == 1 && m->symbols_[0].name != "main") {
166	            m->symbols_.push_back({"main", min_vma});
167	        }
168	    } else {
169	        m->symbols_.push_back({"main", min_vma});
170	    }
171	
172	    *out = m;
173	    return VX_SUCCESS;
174	}
175	
176	vx_result_t Module::get_kernel(const char* name, Kernel** out) {
177	    if (!name || !out) return VX_ERR_INVALID_VALUE;
178	    std::lock_guard<std::mutex> g(kcache_mu_);
179	    auto it = kernel_cache_.find(name);
180	    if (it != kernel_cache_.end()) {
181	        it->second->retain();
182	        *out = it->second;
183	        return VX_SUCCESS;
184	    }
185	    for (const auto& s : symbols_) {
186	        if (s.name == name) {
187	            Kernel* k = nullptr;
188	            auto r = Kernel::create(this, s.pc, &k);
189	            if (r != VX_SUCCESS) return r;
190	            // Cache holds a non-owning reference — Kernel's destructor
191	            // removes itself from the cache.
192	            kernel_cache_[name] = k;
193	            // The kernel was created with refcount=1; return that ref to
194	            // the caller. The cache's "reference" is a raw pointer only.
195	            *out = k;
196	            return VX_SUCCESS;
197	        }
198	    }
199	    return VX_ERR_INVALID_VALUE;
200	}
201	
202	// ----------------------------------------------------------------------------
203	// Kernel
204	// ----------------------------------------------------------------------------
205	
206	Kernel::Kernel(Module* mod, uint64_t pc)
207	    : module_(mod), pc_(pc) {
208	    module_->retain();
209	}
210	
211	Kernel::~Kernel() {
212	    // Best-effort removal from the module's cache (in case some lookup
213	    // raced; the cache holds a weak ref so it's safe to leave a dangling
214	    // entry briefly, but cleaning up keeps the map size bounded over
215	    // many create/release cycles of the same kernel name).
216	    if (module_) {
217	        std::lock_guard<std::mutex> g(module_->kcache_mu_);
218	        for (auto it = module_->kernel_cache_.begin();
219	             it != module_->kernel_cache_.end(); ++it) {
220	            if (it->second == this) {
221	                module_->kernel_cache_.erase(it);
222	                break;
223	            }
224	        }
225	        module_->release();
226	    }
227	}
228	
229	vx_result_t Kernel::create(Module* mod, uint64_t pc, Kernel** out) {
230	    if (!mod || !out) return VX_ERR_INVALID_VALUE;
231	    *out = new Kernel(mod, pc);
232	    return VX_SUCCESS;
233	}
234	
235	vx_result_t Kernel::get_max_block_size(uint32_t* x, uint32_t* y, uint32_t* z) {
236	    if (!x || !y || !z) return VX_ERR_INVALID_VALUE;
237	    // Default block size: full warp width × num_warps × 1.
238	    uint64_t nt = 0, nw = 0;
239	    auto* dev = module_->device();
240	    auto r = dev->query_caps(VX_CAPS_NUM_THREADS, &nt);
241	    if (r != VX_SUCCESS) return r;
242	    r = dev->query_caps(VX_CAPS_NUM_WARPS, &nw);
243	    if (r != VX_SUCCESS) return r;
244	    *x = (uint32_t)nt;
245	    *y = (uint32_t)nw;
246	    *z = 1;
247	    return VX_SUCCESS;
248	}
249	
250	} // namespace vx
251	
252	// ============================================================================
253	// C entry points
254	// ============================================================================
255	
256	using namespace vx;
257	
258	extern "C" vx_result_t vx_module_load_file(vx_device_h dev, const char* path,
259	                                           vx_module_h* out) {
260	    VX_C_ENTRY_TRY
261	    if (!dev || !path || !out) return VX_ERR_INVALID_VALUE;
262	    Module* m = nullptr;
263	    auto r = Module::load_file(to_device(dev), path, &m);
264	    if (r != VX_SUCCESS) return r;
265	    *out = to_handle(m);
266	    return VX_SUCCESS;
267	    VX_C_ENTRY_CATCH
268	}
269	
270	extern "C" vx_result_t vx_module_load_bytes(vx_device_h dev, const void* bytes,
271	                                            size_t size, vx_module_h* out) {
272	    VX_C_ENTRY_TRY
273	    if (!dev || !bytes || !out) return VX_ERR_INVALID_VALUE;
274	    Module* m = nullptr;
275	    auto r = Module::load_bytes(to_device(dev), bytes, size, &m);
276	    if (r != VX_SUCCESS) return r;
277	    *out = to_handle(m);
278	    return VX_SUCCESS;
279	    VX_C_ENTRY_CATCH
280	}
281	
282	extern "C" vx_result_t vx_module_retain(vx_module_h mod) {
283	    if (!mod) return VX_ERR_INVALID_HANDLE;
284	    to_module(mod)->retain();
285	    return VX_SUCCESS;
286	}
287	
288	extern "C" vx_result_t vx_module_release(vx_module_h mod) {
289	    if (!mod) return VX_ERR_INVALID_HANDLE;
290	    to_module(mod)->release();
291	    return VX_SUCCESS;
292	}
293	
294	extern "C" vx_result_t vx_module_get_kernel(vx_module_h mod, const char* name,
295	                                            vx_kernel_h* out) {
296	    VX_C_ENTRY_TRY
297	    if (!mod || !name || !out) return VX_ERR_INVALID_VALUE;
298	    Kernel* k = nullptr;
299	    auto r = to_module(mod)->get_kernel(name, &k);
300	    if (r != VX_SUCCESS) return r;
301	    *out = to_handle(k);
302	    return VX_SUCCESS;
303	    VX_C_ENTRY_CATCH
304	}
305	
306	extern "C" vx_result_t vx_kernel_address(vx_kernel_h k, uint64_t* out_addr) {
307	    if (!k || !out_addr) return VX_ERR_INVALID_VALUE;
308	    // The kernel's device function-entry PC (== VX_CSR_CTA_ENTRY at launch).
309	    // Used by the graphics RASTER fragment-dispatch descriptor (frag_entry).
310	    *out_addr = to_kernel(k)->pc();
311	    return VX_SUCCESS;
312	}
313	
314	extern "C" vx_result_t vx_kernel_retain(vx_kernel_h k) {
315	    if (!k) return VX_ERR_INVALID_HANDLE;
316	    to_kernel(k)->retain();
317	    return VX_SUCCESS;
318	}
319	
320	extern "C" vx_result_t vx_kernel_release(vx_kernel_h k) {
321	    if (!k) return VX_ERR_INVALID_HANDLE;
322	    to_kernel(k)->release();
323	    return VX_SUCCESS;
324	}
325	
326	extern "C" vx_result_t vx_kernel_get_max_block_size(vx_kernel_h k,
327	                                                    uint32_t* x, uint32_t* y,
328	                                                    uint32_t* z) {
329	    if (!k) return VX_ERR_INVALID_HANDLE;
330	    return to_kernel(k)->get_max_block_size(x, y, z);
331	}
