22	Queue::Queue(Device* dev, const vx_queue_info_t& info)
23	    : device_(dev),
24	      priority_(static_cast<uint32_t>(info.priority)),
25	      flags_(info.flags) {
26	    device_->retain();
27	    device_->register_queue(this);
28	    worker_ = std::thread([this]{ this->worker_loop(); });
29	}
