31	Queue::~Queue() {
32	    // Drain + stop the worker. Push a shutdown flag and wake the worker;
33	    // it will finish any commands already in the FIFO and then return.
34	    {
35	        std::lock_guard<std::mutex> g(cmd_mu_);
36	        shutdown_ = true;
37	    }
38	    cmd_cv_.notify_all();
39	    if (worker_.joinable()) worker_.join();
40	
41	    if (device_) {
42	        device_->unregister_queue(this);
43	        device_->release();
44	    }
45	}
