47	vx_result_t Queue::create(Device* dev, const vx_queue_info_t* info,
48	                          Queue** out) {
49	    if (!dev || !out) return VX_ERR_INVALID_VALUE;
50	    vx_queue_info_t default_info = {};
51	    default_info.struct_size = sizeof(default_info);
52	    default_info.priority    = VX_QUEUE_PRIORITY_NORMAL;
53	    default_info.flags       = 0;
54	    if (!info) info = &default_info;
55	    if (info->struct_size < sizeof(vx_queue_info_t)) return VX_ERR_INVALID_INFO;
56	    *out = new Queue(dev, *info);
57	    return VX_SUCCESS;
58	}
59	
60	// ============================================================================
61	// Worker loop — processes commands strictly in FIFO order.
62	//
63	// Each command may have a wait-list of events that must complete before its
64	// work runs. The waits happen on the worker thread, so an enqueue gated on
65	// an unsignaled user event does not block the caller. In-order queue
66	// semantics are preserved because there is exactly one worker per Queue.
67	// ============================================================================
68	
69	void Queue::worker_loop() {
70	    while (true) {
71	        Command cmd;
72	        {
73	            std::unique_lock<std::mutex> lk(cmd_mu_);
74	            cmd_cv_.wait(lk, [&]{ return shutdown_ || !commands_.empty(); });
75	            if (commands_.empty()) return;   // shutdown with empty queue
76	            cmd = std::move(commands_.front());
77	            commands_.pop_front();
78	        }
79	
80	        // Wait for each external dependency. wait() blocks the worker but
81	        // not the caller; if a wait fails (event errored), short-circuit
82	        // the command's work and propagate the failure into completion.
83	        vx_result_t r = VX_SUCCESS;
84	        for (Event* dep : cmd.waits) {
85	            if (r == VX_SUCCESS) r = dep->wait(VX_TIMEOUT_INFINITE);
86	            dep->release();
87	        }
88	
89	        uint64_t submit_ns = now_ns();
90	        uint64_t start_ns  = submit_ns;
91	        uint64_t end_ns    = submit_ns;
92	
93	        if (r == VX_SUCCESS && cmd.work) {
94	            r = cmd.work(&start_ns, &end_ns);
95	        }
96	
97	        if (cmd.completion) {
98	            if (profiling_enabled()) {
99	                cmd.completion->set_profile(cmd.queued_ns, submit_ns,
100	                                            start_ns, end_ns);
101	            }
102	            cmd.completion->complete(r);
103	            cmd.completion->release();
104	        }
105	    }
106	}
107	
108	// ============================================================================
109	// enqueue() — common builder: capture waits, allocate completion event,
110	// stuff the command into the FIFO, notify the worker.
111	// ============================================================================
112	
113	vx_result_t Queue::enqueue(Command&& cmd, uint32_t nw, const vx_event_h* w,
114	                           vx_event_h* out) {
115	    if (nw != 0 && !w) return VX_ERR_INVALID_VALUE;
116	
117	    // Retain each wait event so the caller can release them immediately
118	    // after enqueue returns. The worker releases them in turn after each
119	    // wait completes.
120	    cmd.waits.reserve(nw);
121	    for (uint32_t i = 0; i < nw; ++i) {
122	        if (!w[i]) return VX_ERR_INVALID_HANDLE;
123	        Event* e = to_event(w[i]);
124	        e->retain();
125	        cmd.waits.push_back(e);
126	    }
127	
128	    // Completion event — created in QUEUED state. The worker will mark it
129	    // COMPLETE (or set ERROR status) once cmd.work runs. We hand the
130	    // caller one ref and the worker holds one ref.
131	    Event* completion = nullptr;
132	    auto r = Event::create(device_, &completion);
133	    if (r != VX_SUCCESS) {
134	        for (Event* e : cmd.waits) e->release();
135	        return r;
136	    }
137	    completion->retain();           // for the worker
138	    cmd.completion = completion;
139	
140	    if (out) *out = to_handle(completion);
141	    else     completion->release(); // caller doesn't want it — drop caller's ref
142	
143	    {
144	        std::lock_guard<std::mutex> g(cmd_mu_);
145	        commands_.push_back(std::move(cmd));
146	    }
147	    cmd_cv_.notify_one();
148	    return VX_SUCCESS;
149	}
