151	// ============================================================================
152	// flush / finish
153	// ============================================================================
154	
155	vx_result_t Queue::flush() {
156	    // The worker is already woken on each enqueue, so this is effectively
157	    // a no-op sync point for higher layers.
158	    cmd_cv_.notify_one();
159	    return VX_SUCCESS;
160	}
161	
162	vx_result_t Queue::finish(uint64_t timeout_ns) {
163	    // Enqueue a sentinel barrier and wait for its completion event. This
164	    // is the in-order-queue contract: after finish returns, every
165	    // previously enqueued command has completed (the barrier sits behind
166	    // them in FIFO order).
167	    vx_event_h ev = nullptr;
168	    auto r = this->enqueue_barrier(0, nullptr, &ev);
169	    if (r != VX_SUCCESS) return r;
170	    r = to_event(ev)->wait(timeout_ns);
171	    to_event(ev)->release();
172	    return r;
173	}
