175	// ============================================================================
176	// Enqueue primitives — each wraps a Platform call into a Command lambda.
177	// ============================================================================
178	
179	vx_result_t Queue::enqueue_write(Buffer* dst, uint64_t off, const void* host,
180	                                 uint64_t sz, uint32_t nw,
181	                                 const vx_event_h* w, vx_event_h* out) {
182	    if (!dst || (!host && sz != 0)) return VX_ERR_INVALID_VALUE;
183	    if (off + sz > dst->size())     return VX_ERR_INVALID_VALUE;
184	
185	    // Retain dst for the worker's lifetime — caller may release the buffer
186	    // immediately after enqueue returns (matches OpenCL retain semantics).
187	    dst->retain();
188	    Command cmd;
189	    cmd.queued_ns = now_ns();
190	    cmd.work = [this, dst, off, host, sz](uint64_t* s, uint64_t* e) {
191	        vx_result_t r;
192	        {
193	            *s = now_ns();
194	            std::lock_guard<std::mutex> g(enqueue_mu_);
195	            // Host->device through the CP's DMA engine (CMD_MEM_WRITE).
196	            r = device_->cp_submit_mem_write(dst->dev_address() + off,
197	                                             host, sz);
198	            *e = now_ns();
199	        }
200	        dst->release();
201	        return r;
202	    };
203	    auto r = this->enqueue(std::move(cmd), nw, w, out);
204	    if (r != VX_SUCCESS) dst->release();
205	    return r;
206	}
207	
208	vx_result_t Queue::enqueue_read(void* host, Buffer* src, uint64_t so,
209	                                uint64_t sz, uint32_t nw,
210	                                const vx_event_h* w, vx_event_h* out) {
211	    if (!src || (!host && sz != 0)) return VX_ERR_INVALID_VALUE;
212	    if (so + sz > src->size())      return VX_ERR_INVALID_VALUE;
213	
214	    src->retain();
215	    Command cmd;
216	    cmd.queued_ns = now_ns();
217	    cmd.work = [this, host, src, so, sz](uint64_t* s, uint64_t* e) {
218	        vx_result_t r;
219	        {
220	            *s = now_ns();
221	            std::lock_guard<std::mutex> g(enqueue_mu_);
222	            // Device->host through the CP's DMA engine (CMD_MEM_READ).
223	            r = device_->cp_submit_mem_read(host,
224	                                            src->dev_address() + so, sz);
225	            *e = now_ns();
226	        }
227	        src->release();
228	        return r;
229	    };
230	    auto r = this->enqueue(std::move(cmd), nw, w, out);
231	    if (r != VX_SUCCESS) src->release();
232	    return r;
233	}
234	
235	vx_result_t Queue::enqueue_copy(Buffer* dst, uint64_t do_, Buffer* src,
236	                                uint64_t so, uint64_t sz, uint32_t nw,
237	                                const vx_event_h* w, vx_event_h* out) {
238	    if (!dst || !src)               return VX_ERR_INVALID_VALUE;
239	    if (do_ + sz > dst->size())     return VX_ERR_INVALID_VALUE;
240	    if (so + sz > src->size())      return VX_ERR_INVALID_VALUE;
241	
242	    dst->retain();
243	    src->retain();
244	    Command cmd;
245	    cmd.queued_ns = now_ns();
246	    cmd.work = [this, dst, do_, src, so, sz](uint64_t* s, uint64_t* e) {
247	        vx_result_t r;
248	        {
249	            *s = now_ns();
250	            std::lock_guard<std::mutex> g(enqueue_mu_);
251	            // Device->device through the CP's DMA engine (CMD_MEM_COPY).
252	            r = device_->cp_submit_mem_copy(dst->dev_address() + do_,
253	                                            src->dev_address() + so, sz);
254	            *e = now_ns();
255	        }
256	        src->release();
257	        dst->release();
258	        return r;
259	    };
260	    auto r = this->enqueue(std::move(cmd), nw, w, out);
261	    if (r != VX_SUCCESS) { src->release(); dst->release(); }
262	    return r;
263	}
264	
265	vx_result_t Queue::enqueue_launch(const vx_launch_info_t* info,
266	                                  uint32_t nw, const vx_event_h* w,
267	                                  vx_event_h* out) {
268	    if (!info) return VX_ERR_INVALID_VALUE;
269	    if (info->struct_size < sizeof(vx_launch_info_t))
270	        return VX_ERR_INVALID_INFO;
271	    if (info->ndim > 3) return VX_ERR_INVALID_VALUE;
272	    if (info->args_size != 0 && !info->args_host) return VX_ERR_INVALID_VALUE;
273	
274	    // info->kernel is a vx_kernel_h (vx_module_get_kernel). NULL is the legacy
275	    // escape hatch — the caller pre-programmed the PC DCRs itself. Retain the
276	    // kernel for the worker's lifetime so the underlying module image
277	    // (Kernel → Module → image Buffer) stays alive until the launch retires,
278	    // even if the caller releases the kernel immediately. The launch PCs are
279	    // derived from this handle inside the work lambda, so it is the only
280	    // kernel-state we capture.
281	    Kernel* kernel = (info->kernel != nullptr) ? to_kernel(info->kernel) : nullptr;
282	    if (kernel) kernel->retain();
283	
284	    // Copy the args block now so the caller can free/reuse `info` (and the
285	    // memory it points at) the instant enqueue returns. An empty blob is the
286	    // legacy escape hatch — the caller pre-programmed the ARG DCRs itself.
287	    std::vector<uint8_t> args_blob;
288	    if (info->args_host && info->args_size > 0) {
289	        const uint8_t* p = static_cast<const uint8_t*>(info->args_host);
290	        args_blob.assign(p, p + info->args_size);
291	    }
292	
293	    // Capture the launch descriptor by value into the work lambda so the
294	    // caller can free/reuse `info` immediately after enqueue returns.
295	    // ndim==0 is the legacy escape hatch — grid/block DCRs are left to the
296	    // host's prior vx_dcr_write calls (matches legacy vx_start semantics);
297	    // kernel==NULL and args_host==NULL are the analogous PC / ARG hatches.
298	    const uint32_t ndim      = info->ndim;
299	    const uint32_t lmem_size = info->lmem_size;
300	    std::array<uint32_t, 3> grid_in  = {1, 1, 1};
301	    std::array<uint32_t, 3> block_in = {1, 1, 1};
302	    for (uint32_t i = 0; i < ndim; ++i) {
303	        grid_in [i] = info->grid_dim [i];
304	        block_in[i] = info->block_dim[i];
305	    }
306	    // Cluster shape (CTAs guaranteed co-resident on a core). Normalise
307	    // zero entries to 1 (no grouping). Validate that grid_dim is a whole
308	    // multiple of cluster_dim along each in-use axis.
309	    std::array<uint32_t, 3> lg_in = {1, 1, 1};
310	    for (uint32_t i = 0; i < ndim; ++i) {
311	        uint32_t lg = info->cluster_dim[i];
312	        if (lg == 0) lg = 1;
313	        if (grid_in[i] % lg != 0) {
314	            if (kernel) kernel->release();
315	            return VX_ERR_INVALID_VALUE;
316	        }
317	        lg_in[i] = lg;
318	    }
319	
320	    Command cmd;
321	    cmd.queued_ns = now_ns();
322	    cmd.work = [this, kernel, ndim, lmem_size, grid_in, block_in, lg_in,
323	                args_blob = std::move(args_blob)](uint64_t* s, uint64_t* e) {
324	        // Launch PCs, derived from the retained kernel handle. has_kernel is
325	        // false on the legacy escape hatch (caller pre-programmed the DCRs).
326	        // kernel_pc  → KERNEL_ENTRY: the selected kernel's function entry,
327	        //              read back per-CTA via VX_CSR_CTA_ENTRY.
328	        // program_pc → STARTUP_ADDR: the program image base where every warp
329	        //              begins executing (__vx_cta_entry is linked there).
330	        // Both are XLEN-wide (64-bit on build64) and split across the
331	        // paired *_ADDR0/1 / *_ENTRY0/1 DCRs below.
332	        const bool     has_kernel = (kernel != nullptr);
333	        const uint64_t kernel_pc  = has_kernel ? kernel->pc() : 0;
334	        const uint64_t program_pc = has_kernel ? kernel->module()->base_address() : 0;
335	        // ---- Compute the full KMU descriptor (block_size, warp_step).
336	        uint64_t num_threads = 0, num_warps = 0;
337	        if (ndim > 0) {
338	            auto r = device_->query_caps(VX_CAPS_NUM_THREADS, &num_threads);
339	            if (r != VX_SUCCESS) {
340	                if (kernel) kernel->release();
341	                *s = *e = now_ns(); return r;
342	            }
343	            r = device_->query_caps(VX_CAPS_NUM_WARPS, &num_warps);
344	            if (r != VX_SUCCESS) {
345	                if (kernel) kernel->release();
346	                *s = *e = now_ns(); return r;
347	            }
348	        }
349	        uint32_t eff_block[3] = {1, 1, 1};
350	        for (uint32_t i = 0; i < ndim; ++i) eff_block[i] = block_in[i];
351	        uint32_t block_size = 1;
352	        for (uint32_t i = 0; i < ndim; ++i) block_size *= eff_block[i];
353	        const uint32_t tpw = (uint32_t)num_threads;
354	        const uint32_t ws_x = (ndim >= 1 && eff_block[0]) ?
355	                                tpw % eff_block[0] : 0;
356	        const uint32_t ws_y = (ndim >= 2 && eff_block[1]) ?
357	                                (tpw / eff_block[0]) % eff_block[1] : 0;
358	        const uint32_t ws_z = (ndim >= 3 && eff_block[2]) ?
359	                                (tpw / (eff_block[0] * eff_block[1]))
360	                                  % eff_block[2] : 0;
361	
362	        // ---- Stage the kernel-args blob into a device scratch slot.
363	        // Empty blob → caller pre-programmed the ARG DCRs (legacy path).
364	        uint64_t args_addr   = 0;
365	        bool     args_pooled = false;
366	        bool     args_staged = !args_blob.empty();
367	        if (args_staged) {
368	            auto r = device_->args_slot_acquire(args_blob.size(),
369	                                                &args_addr, &args_pooled);
370	            if (r != VX_SUCCESS) {
371	                if (kernel) kernel->release();
372	                *s = *e = now_ns(); return r;
373	            }
374	            r = device_->dev_write(args_addr, args_blob.data(),
375	                                   args_blob.size());
376	            if (r != VX_SUCCESS) {
377	                device_->args_slot_release(args_addr, args_pooled);
378	                if (kernel) kernel->release();
379	                *s = *e = now_ns();
380	                return r;
381	            }
382	        }
383	
384	        vx_result_t r;
385	        {
386	            std::lock_guard<std::mutex> g(enqueue_mu_);
387	
388	            // Program the KMU DCRs via CMD_DCR_WRITE descriptors through
389	            // the CP ring. has_kernel / args_staged false → caller
390	            // pre-programmed those DCRs (legacy escape hatch).
391	            #define WR(addr, val) do {                                        \
392	                auto _r = device_->cp_submit_dcr_write((addr), (uint32_t)(val)); \
393	                if (_r != VX_SUCCESS) {                                       \
394	                    if (args_staged)                                          \
395	                        device_->args_slot_release(args_addr, args_pooled);   \
396	                    if (kernel) kernel->release();                            \
397	                    *s = *e = now_ns();                                       \
398	                    return _r;                                                \
399	                }                                                             \
400	            } while (0)
401	            if (has_kernel) {
402	                WR(VX_DCR_KMU_STARTUP_ADDR0, program_pc & 0xffffffffu);
403	                WR(VX_DCR_KMU_STARTUP_ADDR1, program_pc >> 32);
404	                WR(VX_DCR_KMU_KERNEL_ENTRY0, kernel_pc & 0xffffffffu);
405	                WR(VX_DCR_KMU_KERNEL_ENTRY1, kernel_pc >> 32);
406	            }
407	            if (args_staged) {
408	                WR(VX_DCR_KMU_STARTUP_ARG0, args_addr & 0xffffffffu);
409	                WR(VX_DCR_KMU_STARTUP_ARG1, args_addr >> 32);
410	            }
411	
412	            if (ndim > 0) {
413	                WR(VX_DCR_KMU_BLOCK_DIM_X, eff_block[0]);
414	                WR(VX_DCR_KMU_BLOCK_DIM_Y, eff_block[1]);
415	                WR(VX_DCR_KMU_BLOCK_DIM_Z, eff_block[2]);
416	                WR(VX_DCR_KMU_GRID_DIM_X,  grid_in[0]);
417	                WR(VX_DCR_KMU_GRID_DIM_Y,  ndim >= 2 ? grid_in[1] : 1);
418	                WR(VX_DCR_KMU_GRID_DIM_Z,  ndim >= 3 ? grid_in[2] : 1);
419	                WR(VX_DCR_KMU_LMEM_SIZE,   lmem_size);
420	                WR(VX_DCR_KMU_BLOCK_SIZE,  block_size);
421	                WR(VX_DCR_KMU_WARP_STEP_X, ws_x);
422	                WR(VX_DCR_KMU_WARP_STEP_Y, ws_y);
423	                WR(VX_DCR_KMU_WARP_STEP_Z, ws_z);
424	                WR(VX_DCR_KMU_CLUSTER_DIM_X, lg_in[0]);
425	                WR(VX_DCR_KMU_CLUSTER_DIM_Y, lg_in[1]);
426	                WR(VX_DCR_KMU_CLUSTER_DIM_Z, lg_in[2]);
427	            }
428	            #undef WR
429	
430	            *s = now_ns();
431	            // cp_submit_launch posts CMD_LAUNCH and polls Q_SEQNUM until
432	            // the engine retires (the engine retires only after Vortex
433	            // signals done, so Q_SEQNUM advance means the kernel
434	            // finished).
435	            r = device_->cp_submit_launch();
436	            *e = now_ns();
437	        }
438	
439	        // Launch retired — the kernel has consumed its args. Return the
440	        // scratch slot to the pool for the next launch.
441	        if (args_staged)
442	            device_->args_slot_release(args_addr, args_pooled);
443	        if (kernel) kernel->release();
444	        return r;
445	    };
446	    auto r = this->enqueue(std::move(cmd), nw, w, out);
447	    if (r != VX_SUCCESS && kernel) kernel->release();
448	    return r;
449	}
