453	// CP wire opcodes for draw-descriptor steps — mirror the CommandProcessor
454	// opcode enum (sim/common/cmd_processor.h) and device.cpp.
455	constexpr uint8_t CP_OP_DCR_WRITE    = 0x04;
456	constexpr uint8_t CP_OP_CACHE_FLUSH  = 0x0A;
457	constexpr uint8_t CP_OP_LAUNCH_QMD   = 0x0B;
458	// Fixed per-step stride in a draw descriptor (28-byte cmd-record prefix).
459	// Must equal CommandProcessor::DRAW_STEP_BYTES.
460	constexpr int     CP_DRAW_STEP_BYTES = 28;
461	
462	// One captured command in an ordered batch / draw bundle. DCR writes carry
463	// (addr,value); launches carry the same state vx_enqueue_launch captures
464	// (retained kernel + copied args + grid/block), resolved to KMU DCRs on the
465	// worker thread.
466	struct CmdRec {
467	    bool                   is_launch = false;
468	    uint32_t               dcr_addr  = 0;
469	    uint32_t               dcr_value = 0;
470	    Kernel*                kernel    = nullptr;   // retained when is_launch
471	    std::vector<uint8_t>   args;
472	    uint32_t               ndim      = 0;
473	    uint32_t               lmem_size = 0;
474	    std::array<uint32_t,3> grid      = {1, 1, 1};
475	    std::array<uint32_t,3> block     = {1, 1, 1};
476	    std::array<uint32_t,3> cluster   = {1, 1, 1};
477	};
478	
479	// Per-launch device-scratch staging: args blob + QMD launch descriptor.
480	struct CmdStaged {
481	    uint64_t args_addr = 0; bool args_pooled = false; bool args_active = false;
482	    uint64_t qmd_addr  = 0; bool qmd_pooled  = false; bool qmd_active  = false;
483	    // Host copy of the packed QMD ([count, count x (dcr_addr, value)]) for
484	    // CPs without the CMD_LAUNCH_QMD decoder (see cmd_submit_launch).
485	    std::vector<uint32_t> qmd_words;
486	};
487	
488	// Validate `commands`, copy into `recs`, retaining launched kernels (recorded
489	// in `retained`). On any validation error the retained kernels are released and
490	// the error is returned; on success the caller owns `retained`.
491	vx_result_t cmd_build_recs(const vx_command_t* commands, uint32_t count,
492	                           std::vector<CmdRec>& recs,
493	                           std::vector<Kernel*>& retained) {
494	    recs.reserve(count);
495	    auto fail = [&](vx_result_t e) -> vx_result_t {
496	        for (Kernel* k : retained) k->release();
497	        retained.clear();
498	        return e;
499	    };
500	    for (uint32_t i = 0; i < count; ++i) {
501	        const vx_command_t& c = commands[i];
502	        CmdRec r;
503	        if (c.type == VX_COMMAND_DCR_WRITE) {
504	            r.dcr_addr  = c.data.dcr.addr;
505	            r.dcr_value = c.data.dcr.value;
506	        } else if (c.type == VX_COMMAND_LAUNCH) {
507	            const vx_launch_info_t* info = c.data.launch;
508	            if (!info) return fail(VX_ERR_INVALID_VALUE);
509	            if (info->struct_size < sizeof(vx_launch_info_t))
510	                return fail(VX_ERR_INVALID_INFO);
511	            if (info->ndim > 3) return fail(VX_ERR_INVALID_VALUE);
512	            if (info->args_size != 0 && !info->args_host)
513	                return fail(VX_ERR_INVALID_VALUE);
514	            r.is_launch = true;
515	            r.kernel = (info->kernel != nullptr) ? to_kernel(info->kernel) : nullptr;
516	            if (r.kernel) { r.kernel->retain(); retained.push_back(r.kernel); }
517	            if (info->args_host && info->args_size > 0) {
518	                const uint8_t* p = static_cast<const uint8_t*>(info->args_host);
519	                r.args.assign(p, p + info->args_size);
520	            }
521	            r.ndim      = info->ndim;
522	            r.lmem_size = info->lmem_size;
523	            for (uint32_t d = 0; d < info->ndim; ++d) {
524	                r.grid [d] = info->grid_dim [d];
525	                r.block[d] = info->block_dim[d];
526	            }
527	            for (uint32_t d = 0; d < info->ndim; ++d) {
528	                uint32_t lg = info->cluster_dim[d];
529	                if (lg == 0) lg = 1;
530	                if (r.grid[d] % lg != 0) return fail(VX_ERR_INVALID_VALUE);
531	                r.cluster[d] = lg;
532	            }
533	        } else {
534	            return fail(VX_ERR_INVALID_VALUE);
535	        }
536	        recs.push_back(std::move(r));
537	    }
538	    return VX_SUCCESS;
539	}
540	
541	// Stage each launch's args AND its QMD launch descriptor into device scratch.
542	// Both are CP DMAs that must complete BEFORE the ring batch / OP_DRAW is
543	// submitted (the launch's CMD_LAUNCH_QMD reads the QMD from memory at drain
544	// time). The QMD is the KMU descriptor as a {count,(dcr_addr,value)...} list
545	// the CP replays — one launch command in place of ~18 CMD_DCR_WRITEs. Returns
546	// the first error; the caller releases any active slots in `staged`. `tpw` is
547	// threads-per-warp (NUM_THREADS) for the warp_step derivation.
548	vx_result_t cmd_stage_qmds(Device* device_, const std::vector<CmdRec>& recs,
549	                           std::vector<CmdStaged>& staged, uint32_t tpw) {
550	    vx_result_t r = VX_SUCCESS;
551	    for (size_t i = 0; i < recs.size() && r == VX_SUCCESS; ++i) {
552	        const CmdRec& rec = recs[i];
553	        if (!rec.is_launch) continue;
554	        CmdStaged& st = staged[i];
555	
556	        // 1) Args blob.
557	        if (!rec.args.empty()) {
558	            r = device_->args_slot_acquire(rec.args.size(),
559	                                           &st.args_addr, &st.args_pooled);
560	            if (r != VX_SUCCESS) break;
561	            st.args_active = true;
562	            r = device_->dev_write(st.args_addr, rec.args.data(), rec.args.size());
563	            if (r != VX_SUCCESS) break;
564	        }
565	
566	        // 2) KMU descriptor values (same derivation as vx_enqueue_launch).
567	        const bool     has_kernel = (rec.kernel != nullptr);
568	        const uint64_t kernel_pc  = has_kernel ? rec.kernel->pc() : 0;
569	        const uint64_t program_pc = has_kernel
570	                                  ? rec.kernel->module()->base_address() : 0;
571	        uint32_t eff_block[3] = {1, 1, 1};
572	        for (uint32_t d = 0; d < rec.ndim; ++d) eff_block[d] = rec.block[d];
573	        uint32_t block_size = 1;
574	        for (uint32_t d = 0; d < rec.ndim; ++d) block_size *= eff_block[d];
575	        const uint32_t ws_x = (rec.ndim >= 1 && eff_block[0]) ?
576	                                tpw % eff_block[0] : 0;
577	        const uint32_t ws_y = (rec.ndim >= 2 && eff_block[1]) ?
578	                                (tpw / eff_block[0]) % eff_block[1] : 0;
579	        const uint32_t ws_z = (rec.ndim >= 3 && eff_block[2]) ?
580	                                (tpw / (eff_block[0] * eff_block[1]))
581	                                  % eff_block[2] : 0;
582	
583	        // 3) Pack the QMD: [count, then count × (dcr_addr, value)].
584	        std::vector<uint32_t> qmd;
585	        qmd.push_back(0);   // count placeholder
586	        auto put = [&](uint32_t addr, uint32_t val) {
587	            qmd.push_back(addr); qmd.push_back(val);
588	        };
589	        if (has_kernel) {
590	            put(VX_DCR_KMU_STARTUP_ADDR0, uint32_t(program_pc & 0xffffffffu));
591	            put(VX_DCR_KMU_STARTUP_ADDR1, uint32_t(program_pc >> 32));
592	            put(VX_DCR_KMU_KERNEL_ENTRY0, uint32_t(kernel_pc & 0xffffffffu));
593	            put(VX_DCR_KMU_KERNEL_ENTRY1, uint32_t(kernel_pc >> 32));
594	        }
595	        if (st.args_active) {
596	            put(VX_DCR_KMU_STARTUP_ARG0, uint32_t(st.args_addr & 0xffffffffu));
597	            put(VX_DCR_KMU_STARTUP_ARG1, uint32_t(st.args_addr >> 32));
598	        }
599	        if (rec.ndim > 0) {
600	            put(VX_DCR_KMU_BLOCK_DIM_X, eff_block[0]);
601	            put(VX_DCR_KMU_BLOCK_DIM_Y, eff_block[1]);
602	            put(VX_DCR_KMU_BLOCK_DIM_Z, eff_block[2]);
603	            put(VX_DCR_KMU_GRID_DIM_X,  rec.grid[0]);
604	            put(VX_DCR_KMU_GRID_DIM_Y,  rec.ndim >= 2 ? rec.grid[1] : 1);
605	            put(VX_DCR_KMU_GRID_DIM_Z,  rec.ndim >= 3 ? rec.grid[2] : 1);
606	            put(VX_DCR_KMU_LMEM_SIZE,   rec.lmem_size);
607	            put(VX_DCR_KMU_BLOCK_SIZE,  block_size);
608	            put(VX_DCR_KMU_WARP_STEP_X, ws_x);
609	            put(VX_DCR_KMU_WARP_STEP_Y, ws_y);
610	            put(VX_DCR_KMU_WARP_STEP_Z, ws_z);
611	            put(VX_DCR_KMU_CLUSTER_DIM_X, rec.cluster[0]);
612	            put(VX_DCR_KMU_CLUSTER_DIM_Y, rec.cluster[1]);
613	            put(VX_DCR_KMU_CLUSTER_DIM_Z, rec.cluster[2]);
614	        }
615	        qmd[0] = uint32_t((qmd.size() - 1) / 2);   // pair count
616	
617	        // 4) Stage the QMD into device memory when the CP decodes
618	        // CMD_LAUNCH_QMD; otherwise keep only the host copy that
619	        // cmd_submit_launch replays as plain ring commands.
620	        st.qmd_words = std::move(qmd);
621	        if (device_->cp_supports_qmd()) {
622	            const uint64_t qmd_bytes = st.qmd_words.size() * sizeof(uint32_t);
623	            r = device_->args_slot_acquire(qmd_bytes, &st.qmd_addr, &st.qmd_pooled);
624	            if (r != VX_SUCCESS) break;
625	            st.qmd_active = true;
626	            r = device_->dev_write(st.qmd_addr, st.qmd_words.data(), qmd_bytes);
627	            if (r != VX_SUCCESS) break;
628	        }
629	    }
630	    return r;
631	}
632	
633	// Submit one staged launch: CMD_LAUNCH_QMD when the CP decodes it, else
634	// replay the descriptor pairs as CMD_DCR_WRITEs followed by a plain
635	// CMD_LAUNCH (same trailing cache-flush discipline in cp_submit_launch).
636	vx_result_t cmd_submit_launch(Device* device_, const CmdStaged& st) {
637	    if (device_->cp_supports_qmd()) {
638	        return device_->cp_submit_launch_qmd(st.qmd_addr);
639	    }
640	    const auto& qmd = st.qmd_words;
641	    const uint32_t count = qmd.empty() ? 0 : qmd[0];
642	    for (uint32_t k = 0; k < count; ++k) {
643	        auto r = device_->cp_submit_dcr_write(qmd[1 + 2 * k], qmd[2 + 2 * k]);
644	        if (r != VX_SUCCESS) return r;
645	    }
646	    return device_->cp_submit_launch();
647	}
