651	vx_result_t Queue::enqueue_commands(const vx_command_t* commands,
652	                                    uint32_t count, uint32_t nw,
653	                                    const vx_event_h* w, vx_event_h* out) {
654	    if (!commands || count == 0) return VX_ERR_INVALID_VALUE;
655	
656	    std::vector<CmdRec>  recs;
657	    std::vector<Kernel*> retained;   // released if enqueue() fails (work won't run)
658	    auto rb = cmd_build_recs(commands, count, recs, retained);
659	    if (rb != VX_SUCCESS) return rb;
660	
661	    Command cmd;
662	    cmd.queued_ns = now_ns();
663	    cmd.work = [this, recs = std::move(recs)](uint64_t* s, uint64_t* e)
664	                   -> vx_result_t {
665	        // Device occupancy for the KMU warp_step computation (same as
666	        // enqueue_launch); resolved once for the whole batch.
667	        uint64_t num_threads = 0, num_warps = 0;
668	        auto rq = device_->query_caps(VX_CAPS_NUM_THREADS, &num_threads);
669	        if (rq == VX_SUCCESS)
670	            rq = device_->query_caps(VX_CAPS_NUM_WARPS, &num_warps);
671	        if (rq != VX_SUCCESS) {
672	            for (const CmdRec& rec : recs) if (rec.kernel) rec.kernel->release();
673	            *s = *e = now_ns();
674	            return rq;
675	        }
676	
677	        // Phase 1 — stage each launch's args + QMD into device scratch.
678	        std::vector<CmdStaged> staged(recs.size());
679	        const uint32_t tpw = (uint32_t)num_threads; (void)num_warps;
680	        vx_result_t r = cmd_stage_qmds(device_, recs, staged, tpw);
681	
682	        // Phase 2 — emit the whole sequence as one ring batch: each launch is a
683	        // single CMD_LAUNCH_QMD (the CP replays the staged descriptor); FF/state
684	        // DCR writes pass through directly. One doorbell, one poll.
685	        if (r == VX_SUCCESS) {
686	            std::lock_guard<std::mutex> g(enqueue_mu_);
687	            *s = now_ns();
688	            device_->cp_batch_begin();
689	            for (size_t i = 0; i < recs.size(); ++i) {
690	                const CmdRec& rec = recs[i];
691	                r = rec.is_launch
692	                  ? cmd_submit_launch(device_, staged[i])
693	                  : device_->cp_submit_dcr_write(rec.dcr_addr, rec.dcr_value);
694	                if (r != VX_SUCCESS) break;
695	            }
696	            // Always close the batch (commit + poll + drain) even on a mid-batch
697	            // error so the partial sequence retires and the lock releases.
698	            auto re = device_->cp_batch_end();
699	            if (r == VX_SUCCESS) r = re;
700	            *e = now_ns();
701	        } else {
702	            *s = *e = now_ns();
703	        }
704	
705	        // Batch drained → release the args + QMD scratch slots and the kernels.
706	        for (auto& st : staged) {
707	            if (st.args_active) device_->args_slot_release(st.args_addr, st.args_pooled);
708	            if (st.qmd_active)  device_->args_slot_release(st.qmd_addr,  st.qmd_pooled);
709	        }
710	        for (const CmdRec& rec : recs) if (rec.kernel) rec.kernel->release();
711	        return r;
712	    };
713	
714	    auto r = this->enqueue(std::move(cmd), nw, w, out);
715	    if (r != VX_SUCCESS) {                 // work lambda won't run → release kernels
716	        for (Kernel* k : retained) k->release();
717	        return r;
718	    }
719	    return r;
720	}
