722	vx_result_t Queue::enqueue_draw(const vx_command_t* commands,
723	                                uint32_t count, uint32_t nw,
724	                                const vx_event_h* w, vx_event_h* out) {
725	    if (!commands || count == 0) return VX_ERR_INVALID_VALUE;
726	
727	    std::vector<CmdRec>  recs;
728	    std::vector<Kernel*> retained;
729	    auto rb = cmd_build_recs(commands, count, recs, retained);
730	    if (rb != VX_SUCCESS) return rb;
731	
732	    Command cmd;
733	    cmd.queued_ns = now_ns();
734	    cmd.work = [this, recs = std::move(recs)](uint64_t* s, uint64_t* e)
735	                   -> vx_result_t {
736	        // Resolve occupancy (warp_step) + core count (per-stage cache flush).
737	        uint64_t num_threads = 0, num_warps = 0, num_cores = 0;
738	        auto rq = device_->query_caps(VX_CAPS_NUM_THREADS, &num_threads);
739	        if (rq == VX_SUCCESS)
740	            rq = device_->query_caps(VX_CAPS_NUM_WARPS, &num_warps);
741	        if (rq == VX_SUCCESS)
742	            rq = device_->query_caps(VX_CAPS_NUM_CORES, &num_cores);
743	        if (rq != VX_SUCCESS) {
744	            for (const CmdRec& rec : recs) if (rec.kernel) rec.kernel->release();
745	            *s = *e = now_ns();
746	            return rq;
747	        }
748	
749	        // Phase 1 — stage each launch's args + QMD into device scratch.
750	        std::vector<CmdStaged> staged(recs.size());
751	        const uint32_t tpw = (uint32_t)num_threads; (void)num_warps;
752	        vx_result_t r = cmd_stage_qmds(device_, recs, staged, tpw);
753	
754	        // Phase 2 — build the resident draw descriptor: [u32 num_steps] then
755	        // 28-byte cmd-record steps. A launch becomes a CMD_LAUNCH_QMD step
756	        // followed by a CMD_CACHE_FLUSH step — the same sequence the ring batch
757	        // streams (cp_submit_launch_qmd appends a flush after every launch), so
758	        // OP_DRAW executes a byte-identical program. The whole draw is then a
759	        // single OP_DRAW ring command the CP expands on-device.
760	        //
761	        // Only when the CP advertises OP_DRAW decode (CP DEV_CAPS bit 25). On a
762	        // CP without it (e.g. an RTL CP whose OP_DRAW mirror is not yet
763	        // synth-validated), fall back to streaming the same launches + DCRs as a
764	        // ring batch — functionally identical, just N ring commands instead of 1.
765	        // Draw bundles embed CP_OP_LAUNCH_QMD steps, so OP_DRAW also requires
766	        // the QMD decoder (and its staged descriptors).
767	        const bool use_op_draw = device_->cp_supports_draw()
768	                              && device_->cp_supports_qmd();
769	        uint64_t desc_addr = 0; bool desc_pooled = false; bool desc_active = false;
770	        if (r == VX_SUCCESS && use_op_draw) {
771	            std::vector<uint8_t> desc(4, 0);   // header placeholder
772	            uint32_t num_steps = 0;
773	            auto put_step = [&](uint8_t opcode, uint64_t a0, uint64_t a1) {
774	                uint8_t step[CP_DRAW_STEP_BYTES] = {0};
775	                step[0] = opcode;
776	                std::memcpy(step + 4,  &a0, sizeof(a0));
777	                std::memcpy(step + 12, &a1, sizeof(a1));
778	                desc.insert(desc.end(), step, step + CP_DRAW_STEP_BYTES);
779	                ++num_steps;
780	            };
781	            for (size_t i = 0; i < recs.size(); ++i) {
782	                const CmdRec& rec = recs[i];
783	                if (rec.is_launch) {
784	                    put_step(CP_OP_LAUNCH_QMD, staged[i].qmd_addr, 0);
785	                    put_step(CP_OP_CACHE_FLUSH, num_cores, 0);
786	                } else {
787	                    put_step(CP_OP_DCR_WRITE, rec.dcr_addr, rec.dcr_value);
788	                }
789	            }
790	            std::memcpy(desc.data(), &num_steps, sizeof(num_steps));
791	            r = device_->args_slot_acquire(desc.size(), &desc_addr, &desc_pooled);
792	            if (r == VX_SUCCESS) {
793	                desc_active = true;
794	                r = device_->dev_write(desc_addr, desc.data(), desc.size());
795	            }
796	        }
797	
798	        // Phase 3 — submit. OP_DRAW: one ring command the CP expands on-device,
799	        // draining each launch (the inter-stage barrier) with no host between.
800	        // Fallback: the same sequence as a single ring batch (one doorbell).
801	        if (r == VX_SUCCESS) {
802	            std::lock_guard<std::mutex> g(enqueue_mu_);
803	            *s = now_ns();
804	            if (use_op_draw) {
805	                r = device_->cp_submit_draw(desc_addr);
806	            } else {
807	                device_->cp_batch_begin();
808	                for (size_t i = 0; i < recs.size(); ++i) {
809	                    const CmdRec& rec = recs[i];
810	                    r = rec.is_launch
811	                      ? cmd_submit_launch(device_, staged[i])
812	                      : device_->cp_submit_dcr_write(rec.dcr_addr, rec.dcr_value);
813	                    if (r != VX_SUCCESS) break;
814	                }
815	                auto re = device_->cp_batch_end();
816	                if (r == VX_SUCCESS) r = re;
817	            }
818	            *e = now_ns();
819	        } else {
820	            *s = *e = now_ns();
821	        }
822	
823	        if (desc_active) device_->args_slot_release(desc_addr, desc_pooled);
824	        for (auto& st : staged) {
825	            if (st.args_active) device_->args_slot_release(st.args_addr, st.args_pooled);
826	            if (st.qmd_active)  device_->args_slot_release(st.qmd_addr,  st.qmd_pooled);
827	        }
828	        for (const CmdRec& rec : recs) if (rec.kernel) rec.kernel->release();
829	        return r;
830	    };
831	
832	    auto r = this->enqueue(std::move(cmd), nw, w, out);
833	    if (r != VX_SUCCESS) {
834	        for (Kernel* k : retained) k->release();
835	        return r;
836	    }
837	    return r;
838	}
