840	vx_result_t Queue::enqueue_barrier(uint32_t nw, const vx_event_h* w,
841	                                   vx_event_h* out) {
842	    // A barrier is a no-op work item; its purpose is to introduce a
843	    // synchronization point that completes only after all waits resolve.
844	    Command cmd;
845	    cmd.queued_ns = now_ns();
846	    cmd.work = [](uint64_t* s, uint64_t* e) {
847	        uint64_t t = now_ns();
848	        *s = t; *e = t;
849	        return VX_SUCCESS;
850	    };
851	    return this->enqueue(std::move(cmd), nw, w, out);
852	}
