854	// ============================================================================
855	// Rect-DMA helpers — software fallback for the *_rect enqueues. Each rect is
856	// decomposed into linear transfers; a future CP DMA descriptor with native
857	// 3D stride can replace the per-row loop without an API change.
858	// ============================================================================
859	
860	namespace {
861	
862	struct ResolvedRect {
863	    size_t region[3];
864	    size_t buffer_origin[3];
865	    size_t host_origin[3];
866	    size_t buffer_row, buffer_slice;
867	    size_t host_row, host_slice;
868	};
869	
870	// Apply OpenCL pitch defaults (0 row pitch -> region[0]; 0 slice pitch ->
871	// region[1] * row_pitch) and reject a degenerate region or a pitch too
872	// small to hold its row / slice.
873	vx_result_t resolve_rect(const vx_rect_info_t& in, ResolvedRect* out) {
874	    for (int i = 0; i < 3; ++i) {
875	        out->region[i]        = in.region[i];
876	        out->buffer_origin[i] = in.buffer_origin[i];
877	        out->host_origin[i]   = in.host_origin[i];
878	    }
879	    if (in.region[0] == 0 || in.region[1] == 0 || in.region[2] == 0)
880	        return VX_ERR_INVALID_VALUE;
881	    out->buffer_row   = in.buffer_row_pitch   ? in.buffer_row_pitch
882	                                              : in.region[0];
883	    out->buffer_slice = in.buffer_slice_pitch ? in.buffer_slice_pitch
884	                                              : out->buffer_row * in.region[1];
885	    out->host_row     = in.host_row_pitch     ? in.host_row_pitch
886	                                              : in.region[0];
887	    out->host_slice   = in.host_slice_pitch   ? in.host_slice_pitch
888	                                              : out->host_row * in.region[1];
889	    if (out->buffer_row < in.region[0] || out->host_row < in.region[0])
890	        return VX_ERR_INVALID_VALUE;
891	    if (out->buffer_slice < out->buffer_row * in.region[1] ||
892	        out->host_slice   < out->host_row   * in.region[1])
893	        return VX_ERR_INVALID_VALUE;
894	    return VX_SUCCESS;
895	}
896	
897	// Byte offset of row `row` of slice `sl` within one side of the rect.
898	uint64_t rect_off(const size_t origin[3], size_t row_pitch, size_t slice_pitch,
899	                  size_t sl, size_t row) {
900	    return (uint64_t)(origin[2] + sl)  * slice_pitch
901	         + (uint64_t)(origin[1] + row) * row_pitch
902	         + origin[0];
903	}
904	
905	// Highest byte (exclusive) one side of the rect touches — for bounds checks.
906	uint64_t rect_span(const size_t region[3], const size_t origin[3],
907	                   size_t row_pitch, size_t slice_pitch) {
908	    return rect_off(origin, row_pitch, slice_pitch,
909	                    region[2] - 1, region[1] - 1) + region[0];
910	}
911	
912	// Walk the rect, invoking row_fn(buffer_off, host_off, len) for each
913	// contiguous run — once for the whole rect when it is fully contiguous,
914	// otherwise once per row. Stops at the first failing transfer.
915	template <class Fn>
916	vx_result_t rect_for_each(const ResolvedRect& r, Fn&& row_fn) {
917	    const bool contig =
918	        r.buffer_row   == r.region[0] &&
919	        r.host_row     == r.region[0] &&
920	        r.buffer_slice == r.region[1] * r.region[0] &&
921	        r.host_slice   == r.region[1] * r.region[0];
922	    if (contig) {
923	        return row_fn(
924	            rect_off(r.buffer_origin, r.buffer_row, r.buffer_slice, 0, 0),
925	            rect_off(r.host_origin,   r.host_row,   r.host_slice,   0, 0),
926	            (uint64_t)r.region[0] * r.region[1] * r.region[2]);
927	    }
928	    for (size_t sl = 0; sl < r.region[2]; ++sl) {
929	        for (size_t row = 0; row < r.region[1]; ++row) {
930	            auto rc = row_fn(
931	                rect_off(r.buffer_origin, r.buffer_row, r.buffer_slice, sl, row),
932	                rect_off(r.host_origin,   r.host_row,   r.host_slice,   sl, row),
933	                (uint64_t)r.region[0]);
934	            if (rc != VX_SUCCESS) return rc;
935	        }
936	    }
937	    return VX_SUCCESS;
938	}
939	
940	} // namespace
