942	vx_result_t Queue::enqueue_read_rect(void* host_dst, Buffer* src,
943	                                     const vx_rect_info_t* info,
944	                                     uint32_t nw, const vx_event_h* w,
945	                                     vx_event_h* out) {
946	    if (!src || !host_dst || !info)                  return VX_ERR_INVALID_VALUE;
947	    if (info->struct_size < sizeof(vx_rect_info_t))  return VX_ERR_INVALID_INFO;
948	    ResolvedRect rr;
949	    auto r = resolve_rect(*info, &rr);
950	    if (r != VX_SUCCESS) return r;
951	    if (rect_span(rr.region, rr.buffer_origin, rr.buffer_row, rr.buffer_slice)
952	        > src->size())
953	        return VX_ERR_INVALID_VALUE;
954	
955	    src->retain();
956	    Command cmd;
957	    cmd.queued_ns = now_ns();
958	    cmd.work = [this, host_dst, src, rr](uint64_t* s, uint64_t* e) {
959	        vx_result_t rc;
960	        {
961	            *s = now_ns();
962	            std::lock_guard<std::mutex> g(enqueue_mu_);
963	            rc = rect_for_each(rr, [&](uint64_t bo, uint64_t ho, uint64_t len) {
964	                return device_->dev_read((uint8_t*)host_dst + ho,
965	                                         src->dev_address() + bo, len);
966	            });
967	            *e = now_ns();
968	        }
969	        src->release();
970	        return rc;
971	    };
972	    auto rr_enq = this->enqueue(std::move(cmd), nw, w, out);
973	    if (rr_enq != VX_SUCCESS) src->release();
974	    return rr_enq;
975	}
