1012	vx_result_t Queue::enqueue_copy_rect(Buffer* dst, Buffer* src,
1013	                                     const vx_rect_info_t* info,
1014	                                     uint32_t nw, const vx_event_h* w,
1015	                                     vx_event_h* out) {
1016	    if (!dst || !src || !info)                       return VX_ERR_INVALID_VALUE;
1017	    if (info->struct_size < sizeof(vx_rect_info_t))  return VX_ERR_INVALID_INFO;
1018	    ResolvedRect rr;
1019	    auto r = resolve_rect(*info, &rr);
1020	    if (r != VX_SUCCESS) return r;
1021	    // buffer_* describes the destination, host_* the source.
1022	    if (rect_span(rr.region, rr.buffer_origin, rr.buffer_row, rr.buffer_slice)
1023	        > dst->size())
1024	        return VX_ERR_INVALID_VALUE;
1025	    if (rect_span(rr.region, rr.host_origin, rr.host_row, rr.host_slice)
1026	        > src->size())
1027	        return VX_ERR_INVALID_VALUE;
1028	
1029	    dst->retain();
1030	    src->retain();
1031	    Command cmd;
1032	    cmd.queued_ns = now_ns();
1033	    cmd.work = [this, dst, src, rr](uint64_t* s, uint64_t* e) {
1034	        vx_result_t rc;
1035	        {
1036	            *s = now_ns();
1037	            std::lock_guard<std::mutex> g(enqueue_mu_);
1038	            rc = rect_for_each(rr, [&](uint64_t do_, uint64_t so, uint64_t len) {
1039	                return device_->dev_copy(dst->dev_address() + do_,
1040	                                         src->dev_address() + so, len);
1041	            });
1042	            *e = now_ns();
1043	        }
1044	        src->release();
1045	        dst->release();
1046	        return rc;
1047	    };
1048	    auto rr_enq = this->enqueue(std::move(cmd), nw, w, out);
1049	    if (rr_enq != VX_SUCCESS) { src->release(); dst->release(); }
1050	    return rr_enq;
1051	}
