1053	vx_result_t Queue::enqueue_fill_buffer(Buffer* dst, uint64_t offset,
1054	                                       uint64_t size, const void* pattern,
1055	                                       size_t pattern_size, uint32_t nw,
1056	                                       const vx_event_h* w, vx_event_h* out) {
1057	    if (!dst || !pattern)             return VX_ERR_INVALID_VALUE;
1058	    if (pattern_size == 0)            return VX_ERR_INVALID_VALUE;
1059	    if (size % pattern_size != 0)     return VX_ERR_INVALID_VALUE;
1060	    if (offset + size > dst->size())  return VX_ERR_INVALID_VALUE;
1061	
1062	    std::vector<uint8_t> pat(static_cast<const uint8_t*>(pattern),
1063	                             static_cast<const uint8_t*>(pattern) + pattern_size);
1064	    dst->retain();
1065	    Command cmd;
1066	    cmd.queued_ns = now_ns();
1067	    cmd.work = [this, dst, offset, size, pat = std::move(pat)]
1068	               (uint64_t* s, uint64_t* e) {
1069	        vx_result_t r = VX_SUCCESS;
1070	        {
1071	            *s = now_ns();
1072	            std::lock_guard<std::mutex> g(enqueue_mu_);
1073	            // Stage one bounded chunk of the repeated pattern and upload it
1074	            // in a loop — avoids a host allocation the full size of a large
1075	            // fill.
1076	            const uint64_t kChunkCap = 64 * 1024;
1077	            uint64_t chunk = kChunkCap - (kChunkCap % pat.size());  // whole patterns
1078	            if (chunk > size) chunk = size;
1079	            std::vector<uint8_t> staging(chunk);
1080	            for (uint64_t i = 0; i < chunk; i += pat.size())
1081	                std::memcpy(staging.data() + i, pat.data(), pat.size());
1082	            for (uint64_t done = 0; done < size && r == VX_SUCCESS; done += chunk) {
1083	                uint64_t n = std::min<uint64_t>(chunk, size - done);
1084	                r = device_->dev_write(dst->dev_address() + offset + done,
1085	                                       staging.data(), n);
1086	            }
1087	            *e = now_ns();
1088	        }
1089	        dst->release();
1090	        return r;
1091	    };
1092	    auto rc = this->enqueue(std::move(cmd), nw, w, out);
1093	    if (rc != VX_SUCCESS) dst->release();
1094	    return rc;
1095	}
