1097	vx_result_t Queue::enqueue_map(Buffer* buf, uint64_t offset, uint64_t size,
1098	                               uint32_t flags, uint32_t nw,
1099	                               const vx_event_h* w, vx_event_h* out,
1100	                               void** out_host_ptr) {
1101	    if (!buf || !out_host_ptr) return VX_ERR_INVALID_VALUE;
1102	    // Reserve the host mirror now so the caller gets a valid pointer
1103	    // synchronously; the READ population runs on the worker in queue order.
1104	    auto r = buf->map_reserve(offset, size, flags, out_host_ptr);
1105	    if (r != VX_SUCCESS) return r;
1106	
1107	    buf->retain();
1108	    Command cmd;
1109	    cmd.queued_ns = now_ns();
1110	    cmd.work = [this, buf](uint64_t* s, uint64_t* e) {
1111	        vx_result_t rc;
1112	        {
1113	            *s = now_ns();
1114	            std::lock_guard<std::mutex> g(enqueue_mu_);
1115	            rc = buf->map_commit();
1116	            *e = now_ns();
1117	        }
1118	        buf->release();
1119	        return rc;
1120	    };
1121	    r = this->enqueue(std::move(cmd), nw, w, out);
1122	    if (r != VX_SUCCESS) {
1123	        buf->release();
1124	        buf->map_cancel();
1125	        *out_host_ptr = nullptr;
1126	    }
1127	    return r;
1128	}
