1184	vx_result_t Queue::enqueue_signal(Event* ev, uint64_t value,
1185	                                  uint32_t nw, const vx_event_h* w,
1186	                                  vx_event_h* out) {
1187	    if (!ev) return VX_ERR_INVALID_HANDLE;
1188	    // Retain the target event for the duration the work item lives in the
1189	    // queue; release in the work lambda after signaling.
1190	    ev->retain();
1191	    Command cmd;
1192	    cmd.queued_ns = now_ns();
1193	    cmd.work = [ev, value](uint64_t* s, uint64_t* e) {
1194	        *s = now_ns();
1195	        // Host-side timeline signal. The event counter is the authoritative
1196	        // cross-queue rendezvous point (see enqueue_wait_value): advancing it
1197	        // here, in this queue's FIFO order, wakes any worker blocked on the
1198	        // event. No CP ring op — a device-side signal would only matter to a
1199	        // device-side wait, which the single in-order ring cannot support.
1200	        ev->signal(value);
1201	        ev->release();
1202	        *e = now_ns();
1203	        return VX_SUCCESS;
1204	    };
1205	    return this->enqueue(std::move(cmd), nw, w, out);
1206	}
1207	
1208	vx_result_t Queue::enqueue_wait_value(Event* ev, uint64_t value,
1209	                                      uint32_t nw, const vx_event_h* w,
1210	                                      vx_event_h* out) {
1211	    if (!ev) return VX_ERR_INVALID_HANDLE;
1212	    ev->retain();
1213	    Command cmd;
1214	    cmd.queued_ns = now_ns();
1215	    cmd.work = [ev, value](uint64_t* s, uint64_t* e) {
1216	        *s = now_ns();
1217	        // Host-side timeline wait on the event counter. We deliberately do
1218	        // NOT post a device-side CMD_EVENT_WAIT: the CP ring is a single
1219	        // in-order ring shared by every queue, so a blocking wait at its head
1220	        // stalls all commands behind it — including the producer's SIGNAL when
1221	        // that SIGNAL is enqueued on another queue (cross-queue
1222	        // wait-before-signal), which deadlocks. The host counter is
1223	        // authoritative and is advanced by every signal path (Event::signal /
1224	        // Event::complete), so blocking the worker here preserves this queue's
1225	        // in-order semantics without touching the CP ring.
1226	        vx_result_t r = ev->wait_value(value, VX_TIMEOUT_INFINITE);
1227	        ev->release();
1228	        *e = now_ns();
1229	        return r;
1230	    };
1231	    return this->enqueue(std::move(cmd), nw, w, out);
1232	}
