198	        { VX_DCR_KMU_STARTUP_ADDR1, (uint32_t)(pc >> 32)         },
199	        { VX_DCR_KMU_STARTUP_ARG0,  (uint32_t)(argp & 0xffffffffu) },
200	        { VX_DCR_KMU_STARTUP_ARG1,  (uint32_t)(argp >> 32)        },
201	        { VX_DCR_KMU_BLOCK_DIM_X,   full_block[0] },
