#include <common.h>

#include <iostream>
#include <fstream>
#include <list>
#include <cstring>
#include <vector>
#include <unordered_map>
#include <vortex.h>
#include <assert.h>

extern int vx_upload_kernel_bytes(vx_device_h hdevice, const void* content, uint64_t size, vx_buffer_h* hbuffer) {
  if (nullptr == hdevice || nullptr == content || size <= 8 || nullptr == hbuffer)
    return -1;

  auto bytes = reinterpret_cast<const uint64_t*>(content);

  auto min_vma = *bytes++;
  auto max_vma = *bytes++;
  auto bin_size = size - 2 * 8;
  auto runtime_size = (max_vma - min_vma);

  vx_buffer_h _hbuffer;
  CHECK_ERR(vx_mem_reserve(hdevice, min_vma, runtime_size, 0, &_hbuffer), {
    return err;
  });

  // mask binary region as read-only
  CHECK_ERR(vx_mem_access(_hbuffer, 0, bin_size, VX_MEM_READ), {
    vx_mem_free(_hbuffer);
    return err;
  });

  // mark global variables region as read-write
  CHECK_ERR(vx_mem_access(_hbuffer, bin_size, runtime_size - bin_size, VX_MEM_READ_WRITE), {
    vx_mem_free(_hbuffer);
    return err;
  });

  // Upload the kernel binary payload to device memory.
  CHECK_ERR(vx_copy_to_dev(_hbuffer, bytes, 0, bin_size), {
    vx_mem_free(_hbuffer);
    return err;
  });

  // Zero-initialize the BSS region of the kernel image in device memory.
  auto bss_size = runtime_size - bin_size;
  if (bss_size > 0) {
    std::vector<uint8_t> zeros(bss_size, 0);
    CHECK_ERR(vx_copy_to_dev(_hbuffer, zeros.data(), bin_size, bss_size), {
      vx_mem_free(_hbuffer);
      return err;
    });
  }

  *hbuffer = _hbuffer;

  return 0;
}

extern int vx_upload_kernel_file(vx_device_h hdevice, const char* filename, vx_buffer_h* hbuffer) {
  if (nullptr == hdevice || nullptr == filename || nullptr == hbuffer)
    return -1;

  std::ifstream ifs(filename);
  if (!ifs) {
    std::cerr << "Error: " << filename << " not found" << std::endl;
    return -1;
  }

  // read file content
  ifs.seekg(0, ifs.end);
  auto size = ifs.tellg();
  std::vector<char> content(size);
  ifs.seekg(0, ifs.beg);
  ifs.read(content.data(), size);

  // upload buffer
  CHECK_ERR(vx_upload_kernel_bytes(hdevice, content.data(), size, hbuffer), {
    return err;
  });

  return 0;
}

extern int vx_upload_bytes(vx_device_h hdevice, const void* content, uint64_t size, vx_buffer_h* hbuffer) {
  if (nullptr == hdevice || nullptr == content || 0 == size || nullptr == hbuffer)
    return -1;

  vx_buffer_h _hbuffer;

  CHECK_ERR(vx_mem_alloc(hdevice, size, VX_MEM_READ, &_hbuffer), {
    return err;
  });

  CHECK_ERR(vx_copy_to_dev(_hbuffer, content, 0, size), {
    vx_mem_free(_hbuffer);
    return err;
  });

  *hbuffer = _hbuffer;

  return 0;
}

extern int vx_upload_file(vx_device_h hdevice, const char* filename, vx_buffer_h* hbuffer) {
  if (nullptr == hdevice || nullptr == filename || nullptr == hbuffer)
    return -1;

  std::ifstream ifs(filename);
  if (!ifs) {
    std::cerr << "Error: " << filename << " not found" << std::endl;
    return -1;
  }

  // read file content
  ifs.seekg(0, ifs.end);
  auto size = ifs.tellg();
  std::vector<char> content(size);
  ifs.seekg(0, ifs.beg);
  ifs.read(content.data(), size);

  // upload buffer
  CHECK_ERR(vx_upload_bytes(hdevice, content.data(), size, hbuffer), {
    return err;
  });

  return 0;
}

int vx_check_occupancy(vx_device_h hdevice, uint32_t block_size, uint32_t max_localmem) {
   // check block size
  uint64_t warps_per_core, threads_per_warp;
  CHECK_ERR(vx_dev_caps(hdevice, VX_CAPS_NUM_WARPS, &warps_per_core), {
    return err;
  });
  CHECK_ERR(vx_dev_caps(hdevice, VX_CAPS_NUM_THREADS, &threads_per_warp), {
    return err;
  });
  uint32_t threads_per_core = warps_per_core * threads_per_warp;
  if (block_size > threads_per_core) {
    printf("Error: cannot schedule kernel with block_size > threads_per_core (%d,%d)\n", block_size, threads_per_core);
    return -1;
  }

  // calculate thread-limited blocks occupancy
  int warps_per_block = (block_size + threads_per_warp-1) / threads_per_warp;
  int blocks_per_core = warps_per_core / warps_per_block;

  // Validate the kernel's per-block local-memory requirement. The CTA
  // dispatcher admits blocks on a fixed LMEM stride (lmem_size/stride slots,
  // see CtaDispatcher::usable_slots), so a larger per-block request does NOT
  // fail — it simply lowers co-residency. Match that here: the only hard limit
  // is a single block exceeding total LMEM. Requesting more than the
  // thread-limited share just trades occupancy for scratchpad.
  if (max_localmem != 0) {
    uint64_t local_mem_size;
    CHECK_ERR(vx_dev_caps(hdevice, VX_CAPS_LOCAL_MEM_SIZE, &local_mem_size), {
      return err;
    });
    if (max_localmem > local_mem_size) {
      printf("Error: kernel local-memory request exceeds device capacity (%u > %lu)\n",
             max_localmem, (unsigned long)local_mem_size);
      return -1;
    }
    // LMEM-limited co-residency uses the same MEM_BLOCK-aligned stride as the
    // CTA dispatcher; report when LMEM (not threads) caps occupancy.
    uint32_t stride = (max_localmem + VX_CFG_MEM_BLOCK_SIZE - 1u)
                    & ~uint32_t(VX_CFG_MEM_BLOCK_SIZE - 1u);
    int blocks_by_lmem = (int)(local_mem_size / stride);
    if (blocks_by_lmem < blocks_per_core)
      blocks_per_core = blocks_by_lmem;
  }

  (void)blocks_per_core;
  return 0;
}

// Legacy shims over the vortex2.h perf primitives (see device.cpp /
// perf.cpp for the implementations).
extern int vx_mpm_query(vx_device_h hdevice, uint32_t mpm_class, uint32_t addr, uint32_t core_id, uint64_t* value) {
  return (vx_device_mpm_query(hdevice, mpm_class, addr, core_id, value) == VX_SUCCESS) ? 0 : -1;
}

extern int vx_dump_perf(vx_device_h hdevice, FILE* stream) {
  return (vx_device_dump_perf(hdevice, stream) == VX_SUCCESS) ? 0 : -1;
}

