269	    // (bit 24); read once here rather than relying on compile-time #ifdefs.
270	    {
271	        uint32_t dev_caps = 0;
272	        if (p->cp_reg_read(CP_DEV_CAPS, &dev_caps) != VX_SUCCESS)
