274	        vm_enabled_ = (dev_caps & (1u << 24)) != 0;
275	        // SUPPORTS_DRAW (bit 25): the CP decodes CMD_DRAW (OP_DRAW). When clear
276	        // (e.g. an RTL CP without the OP_DRAW mirror yet), vx_enqueue_draw falls
277	        // back to streaming the draw as a ring batch (functionally identical).
278	        cp_supports_draw_ = (dev_caps & (1u << 25)) != 0;
