325	        // lost[] sits past data[].
326	        const uint64_t LOST_BASE = VX_MEM_IO_COUT_ADDR
327	                                 + uint64_t(SLOTS) * 8
328	                                 + uint64_t(SLOTS) * RING;
329	        r = dev_write(LOST_BASE, zeros_meta.data(), zeros_meta.size());
