502	vx_result_t Device::cp_submit_launch() {
503	    // CMD_LAUNCH on-wire layout (cmd_size=12):
504	    //   bytes 0..3   header  { opcode=0x06, flags=0, reserved=0 }
505	    //   bytes 4..11  arg0    unused by VX_cp_launch
506	    uint8_t cl[CP_CL_BYTES] = {0};
507	    cl[0] = CP_OPCODE_LAUNCH;
508	    auto r = cp_submit_cl_(cl);
509	    if (r != VX_SUCCESS) return r;
510	    // Cache coherence: post an explicit cache flush right after the launch
511	    // (ACQUIRE_MEM model) so the host observes coherent kernel results.
512	    r = cp_submit_cache_flush();
513	    if (r != VX_SUCCESS) return r;
514	    // In a batch the flush has only been appended, not retired — defer the
515	    // COUT drain to cp_batch_end (one drain for the whole sequence).
516	    if (cp_in_batch_) return VX_SUCCESS;
517	    // Final COUT drain: the flush has made the kernel's writes coherent, so
518	    // the tail-end console output left in the rings is now safe to read.
519	    return drain_cout();
520	}
