541	vx_result_t Device::cp_submit_draw(uint64_t desc_addr) {
542	    // CMD_DRAW on-wire layout (cmd_size=12):
543	    //   bytes 0..3   header  { opcode=0x0C, flags=0, reserved=0 }
544	    //   bytes 4..11  arg0    draw descriptor device address
545	    // The CP reads the resident descriptor ({num_steps, 28-byte cmd steps...})
546	    // and executes the embedded bundle in order — draining each launch (the
547	    // inter-stage barrier) on-device. The descriptor's per-stage CACHE_FLUSH
548	    // steps make results coherent; a final COUT drain mirrors cp_submit_launch_qmd.
549	    uint8_t cl[CP_CL_BYTES] = {0};
550	    cl[0] = CP_OPCODE_DRAW;
551	    std::memcpy(cl + 4, &desc_addr, sizeof(desc_addr));
552	    auto r = cp_submit_cl_(cl);
553	    if (r != VX_SUCCESS) return r;
554	    if (cp_in_batch_) return VX_SUCCESS;
555	    return drain_cout();
556	}
