558	vx_result_t Device::cp_submit_cache_flush() {
559	    // CMD_CACHE_FLUSH on-wire layout (cmd_size=12):
560	    //   bytes 0..3   header  { opcode=0x0A, flags=0, reserved=0 }
561	    //   bytes 4..11  arg0    number of cores to flush
562	    // The CP sweeps a per-core flush DCR-read across [0, num_cores) and
563	    // retires the command only when the last core's flush completes.
564	    // No-op on write-through cache configs (the Vortex default).
565	    if (cp_num_cores_ == 0) {
566	        auto r = this->query_caps(VX_CAPS_NUM_CORES, &cp_num_cores_);
567	        if (r != VX_SUCCESS) return r;
568	    }
569	    uint8_t cl[CP_CL_BYTES] = {0};
570	    cl[0] = CP_OPCODE_CACHE_FLUSH;
571	    std::memcpy(cl + 4, &cp_num_cores_, sizeof(cp_num_cores_));
572	    return cp_submit_cl_(cl);
573	}
