575	vx_result_t Device::cp_submit_dcr_read(uint32_t addr, uint32_t tag,
576	                                       uint32_t* out_value) {
577	    if (!out_value) return VX_ERR_INVALID_VALUE;
578	    // CMD_DCR_READ on-wire layout (cmd_size=20):
579	    //   bytes 0..3   header  { opcode=0x05, flags=0, reserved=0 }
580	    //   bytes 4..11  arg0    DCR addr (low 12 bits used)
581	    //   bytes 12..19 arg1    tag (data on the DCR bus; e.g. core index
582	    //                        for VX_DCR_BASE_CACHE_FLUSH)
583	    uint8_t cl[CP_CL_BYTES] = {0};
584	    uint32_t* p32 = reinterpret_cast<uint32_t*>(cl);
585	    p32[0] = CP_OPCODE_DCR_RD;
586	    p32[1] = addr;
587	    p32[3] = tag;
588	    auto r = cp_submit_cl_(cl);
589	    if (r != VX_SUCCESS) return r;
590	    // Pick up the response from the CP regfile: VX_cp_dcr_proxy latches
591	    // it on Q_LAST_DCR_RSP at the same offset as the engine's retire.
592	    return platform()->cp_reg_read(CP_Q_LAST_DCR_RSP, out_value);
593	}
