393	vx_result_t Device::cp_submit_cl_(const void* cl) {
394	    auto* p = platform();
395	
396	    // Batch mode: append only — cp_mu_ is already held for the batch, and
397	    // the single doorbell + poll happen in cp_batch_end.
398	    if (cp_in_batch_) {
399	        auto r = cp_ring_append_(cl);
400	        if (r == VX_SUCCESS) cp_batch_target_ = cp_expected_seqnum_;
401	        return r;
402	    }
403	
404	    uint64_t target;
405	    {
406	        // Hold cp_mu_ only through ring write + TAIL doorbell; release before
407	        // polling so concurrent CMD_EVENT_WAIT submitters can post SIGNALs that
408	        // unblock a stalled WAIT at the ring head.
409	        std::lock_guard<std::mutex> g(cp_mu_);
410	
411	        // 1) Write the CL into the ring and reserve its seqnum.
412	        auto r = cp_ring_append_(cl);
413	        if (r != VX_SUCCESS) return r;
414	        target = cp_expected_seqnum_;
415	
416	        // Release fence between the ring memcpy and the doorbell MMIO so
417	        // the CP cannot read a stale ring entry. The MMIO write is a
418	        // serializing UC store on x86 (sfence-equivalent), but on ARM /
419	        // RISC-V and on shells that map host_only BOs WB this fence is
420	        // required for correctness. Cheap on x86; matters everywhere else.
421	        std::atomic_thread_fence(std::memory_order_release);
422	
423	        // 2) Commit the new tail. Atomic-pair: LO stages, HI commits both.
424	        r = p->cp_reg_write(CP_Q_TAIL_LO, uint32_t(cp_tail_ & 0xFFFFFFFFu));
425	        if (r != VX_SUCCESS) return r;
426	        r = p->cp_reg_write(CP_Q_TAIL_HI, uint32_t(cp_tail_ >> 32));
427	        if (r != VX_SUCCESS) return r;
428	    }   // release cp_mu_ — another submitter can now post its own command
429	
430	    // 3) Poll Q_SEQNUM. Reacquire cp_mu_ around each individual MMIO read
431	    // so simx's tick() (which mutates simulator state) and concurrent
432	    // posts from other queues don't race; this still leaves a window
433	    // between iterations for other submitters to come in.
434	    for (;;) {
435	        uint32_t seqnum32 = 0;
436	        vx_result_t r;
437	        {
438	            std::lock_guard<std::mutex> g(cp_mu_);
439	            r = p->cp_reg_read(CP_Q_SEQNUM, &seqnum32);
440	        }
441	        if (r != VX_SUCCESS) return r;
442	        if (uint64_t(seqnum32) >= target) return VX_SUCCESS;
443	        // COUT is drained post-launch only (see cp_submit_launch). The CP
444	        // ring is serial — a COUT CMD_MEM_READ posted here would queue
445	        // behind the very command being waited on; mid-launch draining is not
446	        // possible on a single-queue CP. A kernel that overruns its COUT ring
447	        // within one launch back-pressures until the launch ends.
448	    #ifdef SCOPE
449	        // Same discipline for the SCOPE tap rings: drain continuously so
450	        // the on-chip ring pauses capture only briefly. Best-effort.
451	        (void)vx_scope_drain();
452	    #endif
453	        // No host sleep: each MMIO read already ticks sim cycles.
